import assert from 'node:assert/strict';
import { inflateRawSync } from 'node:zlib';
import { crc32 } from './zip-store.mjs';

// Validate the deterministic, single-volume ZIP profile generated by this
// repository, including old STORE-only packages. This is not a general unzipper.
export function readZipEntries(buffer) {
  assert.ok(buffer.length >= 22, 'Truncated ZIP');
  const end = buffer.length - 22;
  assert.equal(buffer.readUInt32LE(end), 0x06054b50, 'Missing ZIP end record');
  assert.equal(buffer.readUInt16LE(end + 4), 0, 'Multi-volume ZIP unsupported');
  assert.equal(buffer.readUInt16LE(end + 6), 0, 'Multi-volume ZIP unsupported');
  assert.equal(buffer.readUInt16LE(end + 20), 0, 'Unexpected ZIP comment');
  const count = buffer.readUInt16LE(end + 10);
  assert.equal(buffer.readUInt16LE(end + 8), count, 'ZIP entry counts differ');
  const centralSize = buffer.readUInt32LE(end + 12);
  const centralStart = buffer.readUInt32LE(end + 16);
  assert.equal(centralStart + centralSize, end, 'ZIP directory size differs');
  const entries = new Map();
  let local = 0, central = centralStart;
  for (let index = 0; index < count; index += 1) {
    assert.ok(local + 30 <= centralStart && central + 46 <= end, 'Truncated ZIP header');
    assert.equal(buffer.readUInt32LE(local), 0x04034b50, 'Missing local header');
    assert.equal(buffer.readUInt32LE(central), 0x02014b50, 'Missing central header');
    assert.equal(buffer.readUInt32LE(central + 42), local, 'ZIP local offset differs');
    assert.equal(buffer.readUInt16LE(central + 34), 0, 'Multi-volume entry unsupported');
    const flags = buffer.readUInt16LE(local + 6);
    assert.equal(flags, 0x0800, 'Unexpected ZIP flags');
    assert.equal(buffer.readUInt16LE(central + 8), flags, 'ZIP flags differ');
    const method = buffer.readUInt16LE(local + 8);
    assert.ok(method === 0 || method === 8, 'Unsupported ZIP compression');
    assert.equal(buffer.readUInt16LE(central + 10), method, 'ZIP methods differ');
    const crc = buffer.readUInt32LE(local + 14);
    const compressedSize = buffer.readUInt32LE(local + 18);
    const size = buffer.readUInt32LE(local + 22);
    assert.equal(buffer.readUInt32LE(central + 16), crc, 'ZIP CRC headers differ');
    assert.equal(buffer.readUInt32LE(central + 20), compressedSize, 'ZIP compressed sizes differ');
    assert.equal(buffer.readUInt32LE(central + 24), size, 'ZIP expanded sizes differ');
    const nameSize = buffer.readUInt16LE(local + 26);
    const extraSize = buffer.readUInt16LE(local + 28);
    const centralNameSize = buffer.readUInt16LE(central + 28);
    const centralExtraSize = buffer.readUInt16LE(central + 30);
    const commentSize = buffer.readUInt16LE(central + 32);
    const dataStart = local + 30 + nameSize + extraSize;
    const dataEnd = dataStart + compressedSize;
    assert.ok(dataEnd <= centralStart, 'ZIP payload overlaps directory');
    const centralEnd = central + 46 + centralNameSize + centralExtraSize + commentSize;
    assert.ok(centralEnd <= end, 'Truncated ZIP directory');
    const nameBytes = buffer.subarray(local + 30, local + 30 + nameSize);
    assert.deepEqual(nameBytes, buffer.subarray(central + 46, central + 46 + centralNameSize), 'ZIP names differ');
    const name = nameBytes.toString('utf8');
    assert.ok(!entries.has(name), `Duplicate ZIP entry: ${name}`);
    const payload = buffer.subarray(dataStart, dataEnd);
    const data = method === 8 ? inflateRawSync(payload, { maxOutputLength: Math.max(1, size) }) : payload;
    assert.equal(data.length, size, `ZIP expanded size differs: ${name}`);
    assert.equal(crc32(data), crc, `ZIP CRC differs: ${name}`);
    entries.set(name, data);
    local = dataEnd;
    central = centralEnd;
  }
  assert.equal(local, centralStart, 'Unlisted ZIP local data');
  assert.equal(central, end, 'Unlisted ZIP directory data');
  return entries;
}
